-- Clé de rapprochement, DANS la base : c'est elle qui arbitre « doublon ou pas ».
-- Elle doit être identique des deux côtés, donc elle vit ici et pas dans le script Python —
-- lequel ne s'en sert que pour regrouper les tronçons d'un même nom.
CREATE OR REPLACE FUNCTION pg_temp.cle(nom text) RETURNS text AS $$
  SELECT coalesce(string_agg(mot, ' ' ORDER BY ord), '')
  FROM (
    SELECT ord,
           CASE mot
             WHEN 'AV' THEN 'AVENUE' WHEN 'AVE' THEN 'AVENUE'
             WHEN 'BLD' THEN 'BOULEVARD' WHEN 'BVD' THEN 'BOULEVARD'
             WHEN 'BLVD' THEN 'BOULEVARD' WHEN 'BOULD' THEN 'BOULEVARD'
             WHEN 'IMP' THEN 'IMPASSE' WHEN 'RTE' THEN 'ROUTE'
             ELSE mot
           END AS mot
    FROM regexp_split_to_table(
           regexp_replace(
             upper(translate(nom,
               'ÀÁÂÃÄÅÇÈÉÊËÌÍÎÏÑÒÓÔÕÖÙÚÛÜÝàáâãäåçèéêëìíîïñòóôõöùúûüýÿ',
               'AAAAAACEEEEIIIINOOOOOUUUUYaaaaaaceeeeiiiinooooouuuuyy')),
             '[^A-Z0-9]+', ' ', 'g'),
           '\s+') WITH ORDINALITY AS t(mot, ord)
    -- Articles et particules écrasés : « Rue de Moscou » et « Rue Moscou » sont la même rue.
    WHERE mot <> '' AND mot NOT IN ('DE','DU','DES','LA','LE','LES','L','D')
  ) s;
$$ LANGUAGE sql IMMUTABLE;

CREATE TEMP TABLE osm AS
SELECT (f->'properties'->>'nom')::varchar(200)         AS nom,
       (f->'properties'->>'type_street')::varchar(20)  AS type_street,
       (f->'properties'->>'troncons')::int             AS troncons,
       pg_temp.cle(f->'properties'->>'nom')            AS cle,
       ST_Multi(ST_SetSRID(ST_GeomFromGeoJSON(f->'geometry'), 4326)) AS geom
FROM jsonb_array_elements((SELECT doc FROM osm_source)->'features') AS f;
CREATE INDEX ON osm USING GIST (geom);

-- Decoupage sur le contour national : la bbox Overpass deborde sur l'Ethiopie, l'Erythree et le
-- Somaliland. Sans ce filtre, « Zeila-Borama Highway » et « Awash - Assab highway » entraient au
-- referentiel national djiboutien. On DECOUPE plutot qu'on n'exclut : la RN1 continue en
-- Ethiopie, seule sa partie djiboutienne nous concerne.
DELETE FROM osm WHERE NOT EXISTS (
  SELECT 1 FROM public.contour_national c WHERE ST_Intersects(osm.geom, c.geom));
UPDATE osm SET geom = ST_Multi(ST_CollectionExtract(
  ST_Intersection(geom, (SELECT geom FROM public.contour_national LIMIT 1)), 2));
DELETE FROM osm WHERE geom IS NULL OR ST_IsEmpty(geom) OR ST_Length(geom::geography) < 20;

CREATE TEMP TABLE ref AS
SELECT "Id", "Code", "Name", "Type", "Boundary", pg_temp.cle("Name") AS cle FROM public."Streets";
CREATE INDEX ON ref USING GIST ("Boundary");

-- Recouvrement : quelle part de la rue OSM longe une rue existante, à 20 m près ? C'est le
-- garde-fou contre le doublon que le NOM ne voit pas — même voie, orthographe differente.
CREATE TEMP TABLE proximite AS
SELECT o.cle AS cle_osm, r."Id", r."Name", r."Code",
       ST_Length(ST_Intersection(ST_Transform(o.geom,32638), ST_Buffer(ST_Transform(r."Boundary",32638), 20)))
         / NULLIF(ST_Length(ST_Transform(o.geom,32638)),0) AS part,
       ST_Length(r."Boundary"::geography) / NULLIF(ST_Length(o.geom::geography),0) AS rapport_longueur
FROM osm o JOIN ref r ON r."Boundary" IS NOT NULL
 AND ST_DWithin(ST_Transform(o.geom,32638), ST_Transform(r."Boundary",32638), 20);


-- =============================================================================================
-- Rapport AVANT écriture
-- =============================================================================================
-- pgAdmin n'affiche QUE le dernier jeu de résultats d'un script : un rapport placé ici serait
-- calculé puis jeté. On l'empile donc dans une table temporaire, restituée en UNE grille à la
-- fin — après les écritures, pour qu'il décrive l'état réellement obtenu.
CREATE TEMP TABLE rapport(ordre int, section text, detail text, valeur text);

INSERT INTO rapport
SELECT 1, 'bilan', 'routes OSM dans le pays', count(*)::text FROM osm
UNION ALL SELECT 2, 'bilan', 'deja au referentiel (meme nom)', count(DISTINCT o.cle)::text FROM osm o JOIN ref r ON r.cle = o.cle
UNION ALL SELECT 3, 'bilan', '  dont sans geometrie -> remplies', count(DISTINCT o.cle)::text FROM osm o JOIN ref r ON r.cle = o.cle WHERE r."Boundary" IS NULL
UNION ALL SELECT 4, 'bilan', 'doublon probable -> A ARBITRER', count(DISTINCT p.cle_osm)::text FROM proximite p
  WHERE p.part > 0.7 AND p.rapport_longueur BETWEEN 0.5 AND 2 AND p.cle_osm NOT IN (SELECT cle FROM ref)
UNION ALL SELECT 5, 'bilan', 'inserees', count(*)::text FROM osm o
  WHERE o.cle NOT IN (SELECT cle FROM ref)
    AND NOT EXISTS (SELECT 1 FROM proximite p WHERE p.cle_osm=o.cle AND p.part>0.7 AND p.rapport_longueur BETWEEN 0.5 AND 2);

-- Le detail des doublons probables : RIEN n'est ecrit pour ceux-la, ils attendent un arbitrage.
-- La meme liste est deja exportee dans `routes-osm-doublons-a-arbitrer.csv`.
INSERT INTO rapport
SELECT DISTINCT 6, 'doublon a arbitrer', o.nom || '  (OSM)',
       p."Name" || '  [' || p."Code" || ']  — ' || round((p.part*100)::numeric) || ' % du trace'
FROM osm o JOIN proximite p ON p.cle_osm = o.cle
WHERE p.part > 0.7 AND p.rapport_longueur BETWEEN 0.5 AND 2 AND o.cle NOT IN (SELECT cle FROM ref);

-- Seules les DEUX écritures qui suivent sont dans la transaction.
BEGIN;

-- =============================================================================================
-- Écriture 1 — remplir les géométries manquantes des rues DÉJÀ présentes
-- =============================================================================================
-- Ne touche ni au nom, ni au code, ni à l'Id : la rue existe, seule son emprise manquait.
-- `Boundary IS NULL` est la seule condition : on n'écrase JAMAIS un tracé déjà saisi, qui peut
-- venir d'un relevé terrain plus fiable qu'OSM.
UPDATE public."Streets" s
SET "Boundary" = o.geom
FROM osm o
WHERE s."Boundary" IS NULL AND pg_temp.cle(s."Name") = o.cle;

-- =============================================================================================
-- Écriture 2 — insérer les rues absentes
-- =============================================================================================
-- `Code` préfixé `OSM-` : la provenance reste lisible en base, à côté des `SIG-` existants.
-- Le suffixe vient de la clé de rapprochement, donc déjà normalisée et sans accent.
INSERT INTO public."Streets" ("Id", "Code", "Name", "Type", "Boundary")
SELECT gen_random_uuid(),
       left('OSM-' || replace(o.cle, ' ', '-'), 200),
       o.nom, o.type_street, o.geom
FROM osm o
WHERE o.cle NOT IN (SELECT cle FROM ref)
  AND NOT EXISTS (SELECT 1 FROM proximite p
                  WHERE p.cle_osm = o.cle AND p.part > 0.7 AND p.rapport_longueur BETWEEN 0.5 AND 2)
  -- Filet de sécurité : un `Code` déjà pris ferait échouer tout le lot.
  AND NOT EXISTS (SELECT 1 FROM public."Streets" x
                  WHERE x."Code" = left('OSM-' || replace(o.cle, ' ', '-'), 200));

INSERT INTO rapport
SELECT 7, 'Streets apres ecriture', "Type", count(*) || ' lignes, ' || count("Boundary") || ' avec geometrie'
FROM public."Streets" GROUP BY "Type";

-- Remplacer par ROLLBACK pour un essai à blanc : le rapport ci-dessous s'affiche quand même
-- (la table temporaire survit à la transaction), mais rien n'est écrit.
COMMIT;

SELECT section, detail, valeur FROM rapport ORDER BY ordre, detail;
